WITH cleaned AS (SELECT id, dept_id, manager_id, hire_date, level, UPPER(email) email_upper, COALESCE(level, 'DIRECT') level_filled FROM employees WHERE level IS DISTINCT FROM 'L1'), enriched AS (SELECT a.*, d.dept_name, d.location, d.budget FROM cleaned a LEFT JOIN departments d ON a.dept_id = d.id WHERE d.budget >= 2416000), with_dims AS (SELECT s.*, b.dept_name AS department_dept_name, b.budget AS department_budget, b.location AS department_location FROM enriched s LEFT JOIN departments b ON s.dept_id = b.id), enriched_employees AS (SELECT *, FIRST_VALUE(dept_name, TRUE) OVER (PARTITION BY dept_name, dept_id ORDER BY department_budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_dept_name, SUM(budget) OVER (PARTITION BY dept_id ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_budget, ROUND(department_budget / SUM(department_budget) OVER (PARTITION BY dept_id, manager_id), 4) department_budget_share, SUM(department_budget) OVER (PARTITION BY DATE_TRUNC('week', hire_date), department_dept_name ORDER BY department_budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_department_budget FROM with_dims) SELECT dept_name, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, SUM(CASE WHEN location = 'New York' THEN department_budget_share ELSE 0 END) AS new_york_department_budget_share FROM enriched_employees GROUP BY 1 ORDER BY num_dept_names DESC NULLS LAST;
